const DB = {"built":"2026-10-05T16:12:48.433Z","classes":[{"id":"Human","label":"在市場走動找攤位的人（Tourist／Resident 的共同基礎）","note":"Tourist／Resident 在程式碼裡是各自獨立的完整實作，共用規則","attributes":{"interestTarget":{"desc":"興趣目標＝營業中的某類 Vendor，排除這趟已到訪（以店鋪 code 計）的；值域由子類決定","variants":[{"adjective":"一個新來的人（Tourist）","when":"class == Tourist","value":"Vendor (New)","effect":["Passability 只放行 new 攤位","Spawn 數量隨 new 店鋪數"]},{"adjective":"一個熟悉在地的人（Resident）","when":"class == Resident","value":"Vendor (Old)","effect":["Passability 只放行 old 攤位","Spawn 數量隨 old 店鋪數"]}],"status":"implemented"}},"rules":{"passableFor":{"desc":"只有走道、入口、店鋪格可通行（World.passable 白名單），其餘格型（馬路、人行道、牆、設施…）不可通行；攤位格只有等於興趣目標類型才可通行，否則視同牆；走道格上的椅子不影響通行；攤位格 Cell.noEnter（桌面空間、工作桌面混合、工作設備區）即使是興趣目標也不可通行","reads":["Human.interestTarget"],"impl":"agents/tourist.js#passableFor | agents/resident.js#passableFor","status":"implemented","implRefs":["agents/tourist.js#passableFor","agents/resident.js#passableFor"]},"spawnExpected":{"desc":"從入口格（World.entryCells）均勻隨機生成；數量隨興趣目標類型的營業店鋪數增加，另乘外部事件倍率（見 simulator_setting）；再乘時間波段倍率 timeBandMultiplier(agent, 時刻)＝波段倍率，不正規化（0 休市、<1 離峰、1 基準、>1 尖峰）","params":{"TIME_BANDS":{"value":[[4,6,0.5,0.1],[6,9,2,0.3],[9,11,1.5,0.8],[11,13,1,2],[13,16,0.4,1],[16,19,1.5,1.5],[19,22,0.5,0.5]],"unit":"[起, 終) 小時、Resident 倍率、Tourist 倍率","note":"區間外（22–04）倍率 0；高峰：早市 06–09、午間 11–13（Tourist）、傍晚 16–19；設計假設非實測，依傳統市場上午與傍晚高峰＋用餐時間的人流（午間 11–13、傍晚 16–19 高峰；用餐時間只影響人流，不影響人會不會坐下）；自訂值，可覆寫"}},"reads":["Human.interestTarget"],"impl":"agents/tourist.js#spawnExpected | agents/resident.js#spawnExpected | index.html#timeBandMult","status":"implemented","implRefs":["agents/tourist.js#spawnExpected","agents/resident.js#spawnExpected","index.html#timeBandMult"]},"movementSpeed":{"desc":"物理參考常數：1 步＝走 1 格＝1 秒（1 m ÷ 1 m/s），時間系統見 simulator_setting.md「時間系統」","params":{"WALK_SPEED_MPS":{"value":1,"unit":"m/s","note":"Gehl 設計步速"},"CELL_SIZE_M":{"value":1,"unit":"m","note":"研究範圍網格 1 格 = 1 m"}},"status":"reference"},"giveupRule":{"desc":"ticksSinceProgress（距上次到訪新攤位的步數＝秒數）達 GIVEUP_SEC 就離場；到訪新攤位歸零","params":{"GIVEUP_SEC":{"value":1800,"unit":"sec","note":"30 分鐘；Tourist、Resident 共用；自訂值，可覆寫"}},"impl":"agents/tourist.js#move | agents/resident.js#move（inline）","status":"implemented","implRefs":["agents/tourist.js#move","agents/resident.js#move"]},"exitStep":{"desc":"站在攤位格裡又沒有下一個目標 → 多來源 BFS（起點＝全走道格）走最近走道出去，不閒晃","reads":["Resident.bfsFieldFromTargets"],"impl":"agents/tourist.js#exitStep | agents/resident.js#exitStep","status":"implemented","implRefs":["agents/tourist.js#exitStep","agents/resident.js#exitStep"]},"visitRule":{"desc":"Visit Rule：到訪店鋪＝所在格 Cell.shopsReach（該格與上下左右相鄰攤位格所屬店鋪，加上擺椅時段內 occupiedBy 含該店的椅子格）；店鋪狀態＝興趣目標且這趟沒到訪過 → 到訪（visited 加入、ticksSinceProgress 歸零、_visitTick 加量），隨即走 chairSeating；一步最多到訪一家。桌面與設備格不能進，所以到訪不靠踏進店鋪格","reads":["Cell.occupiedBy","shop.state","Human.interestTarget"],"writes":["Human.giveupRule"],"impl":"agents/cell.js#shopsReach | agents/tourist.js#step | agents/resident.js#step","status":"implemented","implRefs":["agents/cell.js#shopsReach","agents/tourist.js#step","agents/resident.js#step"]},"chairSlowdown":{"desc":"Chair Slowdown Rule：走進有椅子的走道格（Chair_Mobility：擺椅時段內且 Cell.occupiedBy 裡有營業中的店）→ 在那格多停 CHAIR_SLOW_SEC 秒（步）才能再移動；椅子不擋路也不擋視線；停留期間 ticksSinceProgress 照常累加","params":{"CHAIR_SLOW_SEC":{"value":1,"unit":"sec","note":"自訂值，可覆寫"}},"reads":["Cell.occupiedBy","shop.state","daySec","Human.giveupRule"],"impl":"agents/cell.js#slowIfChair | agents/cell.js#tickPause | agents/tourist.js#move | agents/resident.js#move","status":"implemented","implRefs":["agents/cell.js#slowIfChair","agents/cell.js#tickPause","agents/tourist.js#move","agents/resident.js#move"]},"chairTieBreak":{"desc":"Chair Avoidance Rule：選下一步時若多個鄰格走場值一樣小 → 優先選沒有椅子的格子（非 Chair_Mobility）；只是平手偏好，不繞遠路，不改尋路方式","reads":["Cell.occupiedBy"],"impl":"agents/cell.js#preferNoChair | agents/tourist.js#greedyStepToward | agents/tourist.js#bestStepByField | agents/resident.js#bestStepByField","status":"implemented","implRefs":["agents/cell.js#preferNoChair","agents/tourist.js#greedyStepToward","agents/tourist.js#bestStepByField","agents/resident.js#bestStepByField"]},"passCostPath":{"desc":"Pass Cost Rule：路徑成本＝路徑上每格 Cell.passCost 總和；Resident 的 BFS 取成本最小路徑，繞路額外步數少於穿過去多出的成本才繞，否則穿過並照 chairSlowdown 多停；牆／設施／不符興趣的攤位不算成本，仍由 passableFor 擋。Tourist 沿用貪婪選步，只受 chairTieBreak 影響","params":{"PASS_COST_OPEN":{"value":1,"unit":"cost","note":"完全開放走道格；自訂值，可覆寫"},"PASS_COST_CHAIR":{"value":2,"unit":"cost","note":"Chair_Mobility 走道格；自訂值，可覆寫"}},"reads":["Cell.passCost","Resident.bfsFieldFromTargets"],"impl":"agents/cell.js#passCost | agents/resident.js#bfsFieldFromTargets","status":"implemented","implRefs":["agents/cell.js#passCost","agents/resident.js#bfsFieldFromTargets"]},"crowdRule":{"desc":"Crowd Rule：所在格 density 未達 CROWD_THRESHOLD 不受影響；達到且未超過 JAM_THRESHOLD → 多停 CROWD_SLOW_SEC 秒；超過 JAM_THRESHOLD（塞住）→ 不再多停，每步 ticksSinceProgress 額外加 JAM_GIVEUP_EXTRA。Tourist、Resident 相同，不看個性；人多不會讓人想靠近（靠近熱鬧的是 Tourist.heatBonus）","params":{"DENSITY_RADIUS":{"value":2,"unit":"cell","note":"density 計算範圍；自訂值，可覆寫"},"CROWD_THRESHOLD":{"value":25,"unit":"人","note":"自訂值，可覆寫"},"JAM_THRESHOLD":{"value":50,"unit":"人","note":"自訂值，可覆寫"},"CROWD_SLOW_SEC":{"value":1,"unit":"sec","note":"自訂值，可覆寫"},"JAM_GIVEUP_EXTRA":{"value":1,"unit":"每步加量","note":"自訂值，可覆寫"}},"reads":["Cell.density"],"writes":["Human.giveupRule"],"impl":"agents/cell.js#crowdReact | agents/cell.js#refreshDensity | agents/tourist.js#move | agents/resident.js#move","status":"implemented","implRefs":["agents/cell.js#crowdReact","agents/cell.js#refreshDensity","agents/tourist.js#move","agents/resident.js#move"]},"chairSeating":{"desc":"Chair Seating Rule：成功到訪新店鋪的當下，若該店有擺出椅子、seatsTaken < 座位數 → 坐下：seatsTaken+1，原地停留 SIT_SEC 秒（步），停完 seatsTaken−1；否則不坐照原本逛完就走；滿座時走到門口仍算到訪（visited 照加、ticksSinceProgress 照歸零）；坐著期間 ticksSinceProgress 不累加（坐下算還在店裡，不然 30 分鐘放棄計時器會把人提早趕走）。daySec（當天第幾秒）定義同 Vendor.chairRule，由呼叫端傳入","params":{"SIT_SEC":{"value":3600,"unit":"sec","note":"60 分鐘；自訂值，可覆寫"}},"reads":["Cell.occupiedBy","Vendor.seatsTaken"],"writes":["Vendor.seatsTaken","Human.giveupRule"],"impl":"agents/cell.js#trySit | agents/cell.js#hasSeat | agents/cell.js#release | agents/tourist.js#move | agents/resident.js#move","status":"implemented","implRefs":["agents/cell.js#trySit","agents/cell.js#hasSeat","agents/cell.js#release","agents/tourist.js#move","agents/resident.js#move"]}}},{"id":"Resident","extends":"Human","label":"熟悉市場的在地居民","attributes":{"personality":{"desc":"無——只有 Tourist 有這個屬性，Resident 不套用 Target Scoring","status":"n/a"}},"rules":{"move":{"desc":"BFS 版：全市場多來源 BFS 找最近未訪的營業 Vendor (Old)，純看距離；沒有目標或不可達且站在攤位格就 exitStep，否則隨機走","ref":"99_spec/isovist_algorithm.md#residentStep","source":"Wayfinding 文獻：熟悉環境者用既有認知地圖抄捷徑 https://pmc.ncbi.nlm.nih.gov/articles/PMC8324579/","reads":["Human.interestTarget","Resident.bfsFieldFromTargets"],"impl":"agents/resident.js#move","status":"implemented","implRefs":["agents/resident.js#move"]},"bfsFieldFromTargets":{"desc":"多來源 BFS 場（含 stopAt 早停）","impl":"agents/resident.js#bfsFieldFromTargets","status":"implemented","implRefs":["agents/resident.js#bfsFieldFromTargets"]}}},{"id":"Tourist","extends":"Human","label":"想逛新創攤位的訪客","attributes":{"personality":{"desc":"人格特質E人（常數，程式碼沒有存成欄位）","variants":[{"adjective":"一個熱情外向的人（E人）","when":"personality == E","effect":["heatBonus 為正：人多的攤位感覺比較近，優先被選中"]},{"adjective":"一個怕生內向的人（I人）","when":"personality == I","effect":["heatBonus 為負：人多的攤位感覺比較遠，傾向被跳過"],"status":"planned"}],"source":"2026-08-26 課堂筆記：E 人向人多的地方靠近，I 人相反","status":"implemented"}},"rules":{"move":{"desc":"isovist 版：找可見未訪目標（依 Target Scoring）→ 找不到且站在攤位格就 exitStep → 否則跟隨可見同伴 → 都沒有就隨機走","ref":"99_spec/isovist_algorithm.md#touristStep","reads":["Human.interestTarget","Tourist.findVisibleTarget","Tourist.findVisiblePeer"],"impl":"agents/tourist.js#move","status":"implemented","implRefs":["agents/tourist.js#move"]},"isVisible":{"desc":"可見性判定：牆、設施、建物、任何攤位格（終點除外）擋視線；半徑上限 100 m ≈ 100 格（1 格＝1 m）；同一套也用在看其他 Tourist","params":{"VISION_RADIUS_CELLS":{"value":100,"unit":"cell","note":"100 m ÷ 1 m/格（CELL_SIZE_M）"}},"impl":"agents/tourist.js#isVisible","status":"implemented","implRefs":["agents/tourist.js#isVisible"]},"heatBonus":{"desc":"Target Scoring：分數＝距離−heatBonus(熱度)−chairBonus(店)−visBonus(店)，最小者勝出、同分隨機；熱度讀 touristTrailHeat。Tourist 目前固定走 E人分支","params":{"HEAT_BONUS_TIERS":{"value":{"E":[[25,3],[10,2],[1,1]],"I":[[25,-3],[10,-2],[1,-1]]},"unit":"[熱度門檻, 加成]，由大到小比對，沒中任何一級＝0","note":"只有 E 欄位被程式碼使用"}},"dispatchedBy":"personality","impl":"agents/tourist.js#heatBonus","status":"implemented","implRefs":["agents/tourist.js#heatBonus"]},"chairBonus":{"desc":"Target Scoring 的椅子加分：分數＝距離−heatBonus−chairBonus；該店鋪有擺出椅子、seatsTaken < 座位數 → 減掉 CHAIR_ATTRACT_BONUS（店感覺比較近）；沒擺椅子、或座位已滿 → 0，滿座的店失去吸引力。只有 Tourist 套用，Resident 純看距離","params":{"CHAIR_ATTRACT_BONUS":{"value":2,"unit":"分數","note":"自訂值，可覆寫；不隨椅子數增加"}},"reads":["Cell.occupiedBy","Vendor.seatsTaken"],"impl":"agents/tourist.js#chairBonus","status":"implemented","implRefs":["agents/tourist.js#chairBonus"]},"visBonus":{"desc":"Target Scoring 的可見度加分：分數＝距離−heatBonus−chairBonus−visBonus；店鋪 visibility 超過 VIS_HIGH（顯眼）→ 減掉 VIS_ATTRACT_BONUS，固定值不隨 visibility 增加；隱蔽與一般 → 0（沒有扣分）。只有 Tourist 套用，Resident 不看","params":{"VIS_ATTRACT_BONUS":{"value":1,"unit":"分數","note":"自訂值，可覆寫"}},"reads":["Cell.visibility"],"impl":"agents/tourist.js#visBonus","status":"implemented","implRefs":["agents/tourist.js#visBonus"]},"findVisibleTarget":{"desc":"看得到、未訪的同類目標裡 score 最小者","reads":["Tourist.heatBonus","Tourist.chairBonus","Tourist.visBonus","Tourist.isVisible","Human.interestTarget"],"impl":"agents/tourist.js#findVisibleTarget","status":"implemented","implRefs":["agents/tourist.js#findVisibleTarget"]},"findVisiblePeer":{"desc":"跟隨 fallback：找看得到的其他 Tourist（純距離、不加熱度）","reads":["Tourist.isVisible"],"impl":"agents/tourist.js#findVisiblePeer","status":"implemented","implRefs":["agents/tourist.js#findVisiblePeer"]}}},{"id":"Vendor","label":"攤販（New／Old／Idle 的共同基礎）","note":"三者都不連續走路，狀態變化只有離散判定（固定不動／搬遷）。共用屬性只有 seatsTaken；共用 method 只有 chairRule（椅子是否擺出，看時間與店鋪營業狀態）；Vendor (Idle) 依 generation 直接呼叫 Vendor (New) 的 relocationJudgement()。生存判定以店鋪（同 code 分組）為單位，不是個別 grid 格。","attributes":{"seatsTaken":{"desc":"這家店目前已坐下的人數，起始 0；座位數＝擺椅時段內 occupiedBy（QGIS 標定）含該店 code 的走道格數（一張椅子一個座位，時段外或這家店沒營業為 0），由時間、營業狀態與 occupiedBy 算出、不另存；Human.chairSeating 坐下加 1、停留結束減 1；重設模擬時歸零；擺椅時段結束後已坐的人照原停留計時走完；座位數與 seatsTaken 跟著位置 code 走（搬遷不改 code）","variants":[{"adjective":"一家還有空位的店","when":"seatsTaken < 座位數","effect":["Tourist.chairBonus 有加分","Human.chairSeating 讓人坐下"]},{"adjective":"一家座位坐滿的店","when":"seatsTaken ≥ 座位數","effect":["chairBonus 歸零，人改去別家","走到門口的人照常算到訪、不坐"]}],"source":"2026-10-05 課堂筆記（椅子坐滿用餐時間人會去別家）","status":"implemented","impl":"agents/cell.js#seatsOf | agents/cell.js#trySit","implRefs":["agents/cell.js#seatsOf","agents/cell.js#trySit"]}},"rules":{"chairRule":{"desc":"椅子是否擺出看時間與店鋪營業狀態：當天時刻在 [CHAIR_START_HOUR, CHAIR_END_HOUR)（小時）且該店有營業 → 走道格 occupiedBy（QGIS 標定清單）裡這家店有一張椅子；時段外或沒營業 → 沒有。「營業」＝店鋪狀態 new 或 old；blank 與 Vendor (Idle) 不擺；店鋪以位置 code 為準，搬遷只交換狀態不改 code。不寫入任何狀態：椅子狀態與座位數由時間＋營業狀態＋occupiedBy 當下算出，沒有重設或收椅處理。daySec＝當天第幾秒（程式的 Cell.daySec），由呼叫端傳入。mobility 由此推得。椅子不擋路也不擋視線，行人反應見 Human.chairSlowdown／chairTieBreak／chairSeating 與 Tourist.chairBonus。沒有屬性讓規則分岔","params":{"CHAIR_START_HOUR":{"value":17,"unit":"hour","note":"擺椅起點 17:00（熟食店傍晚才開），全域一組"},"CHAIR_END_HOUR":{"value":22,"unit":"hour","note":"擺椅終點 22:00（不含，熟食店收攤），全域一組"}},"reads":["ERA_DATA.cells[r,c].occupiedBy","daySec","shop.state"],"source":"2026-10-02 課堂筆記（佔據一定跟空間有關，一條一條加反應規則）","status":"implemented","impl":"agents/cell.js#chairsOut | agents/cell.js#isOpen | agents/cell.js#chairCount","implRefs":["agents/cell.js#chairsOut","agents/cell.js#isOpen","agents/cell.js#chairCount"]}}},{"id":"VendorIdle","extends":"Vendor","label":"已關門的攤販（不分新舊），世代屬性繼承自關門前","attributes":{"generation":{"desc":"老／新，繼承自關門前，決定 stepTick() 走哪個分支","variants":[{"adjective":"一間曾經是老字號、現在歇業的店面","when":"generation == old","effect":["走 VendorOld 的 fixed 規則，完全靜止（目前不會被觸發）"]},{"adjective":"一間曾經是新創、現在歇業的店面","when":"generation == new","effect":["先擲 REOPEN_PROB 重開","沒重開走 VendorNew.relocationJudgement"]}],"reads":["VendorOld.fixed"],"status":"implemented"}},"rules":{"reopen":{"desc":"世代＝新：每輪擲 REOPEN_PROB 重新開幕變回 Vendor (New)，人氣、搬遷倒數全歸零；沒重開才搬遷（搬過去仍是已關門狀態）","params":{"REOPEN_PROB":{"value":0.09,"unit":"prob/tick","note":"沿用 BASE_IDLE 數字，自訂、可覆寫"}},"dispatchedBy":"generation","reads":["VendorNew.initStall"],"impl":"agents/vendorIdle.js#stepTick","status":"implemented","implRefs":["agents/vendorIdle.js#stepTick"]}}},{"id":"VendorNew","extends":"Vendor","label":"正常營業中的新創攤位，自己不走路，但會被隨機重新安置","note":"人氣／冷清度記在店鋪（同 code 分組，這次租期），不是攤販身分本身；搬家即歸零重算。","attributes":{"popularity":{"desc":"人氣＝visitHist 近 HEAT_WINDOW 輪到訪次數之和","params":{"HEAT_WINDOW":{"value":2,"unit":"tick"}},"variants":[{"adjective":"一間普通的攤位","when":"popularity < HEAT_HOT_THRESHOLD && coldStreak < COLD_STREAK_THRESHOLD","effect":["走平常關門機率 BASE_IDLE"]},{"adjective":"一間搶手的攤位（人氣旺）","when":"popularity >= HEAT_HOT_THRESHOLD","effect":["關門機率降為 HOT_IDLE","Relocation 暫停倒數、留在原地"]},{"adjective":"一間乏人問津的攤位（冷清）","when":"coldStreak >= COLD_STREAK_THRESHOLD","effect":["關門機率升為 COLD_IDLE"]}],"status":"implemented"},"coldStreak":{"desc":"冷清度＝zeroStreak，連續無到訪的輪數","params":{"COLD_STREAK_THRESHOLD":{"value":3,"unit":"tick","note":"文件沒留原始數字，自訂、可覆寫"}},"status":"implemented"},"closeProbability":{"desc":"關門機率，依 popularity／coldStreak 分支","params":{"BASE_IDLE":{"value":0.09,"unit":"prob/tick"},"HOT_IDLE":{"value":0.04,"unit":"prob/tick"},"COLD_IDLE":{"value":0.25,"unit":"prob/tick"},"HEAT_HOT_THRESHOLD":{"value":2,"unit":"人氣","note":"人氣旺門檻"}},"status":"implemented"}},"rules":{"idleJudgement":{"desc":"關門判定：依 closeProbability 擲骰","impl":"agents/vendorNew.js#idleJudgement","status":"implemented","implRefs":["agents/vendorNew.js#idleJudgement"]},"relocationJudgement":{"desc":"人氣 ≥ HEAT_HOT_THRESHOLD → 暫停倒數；否則 moveTimer−1，≤0 時若有空店鋪依 Site Fertility Weighting 加權挑一間搬過去、原位變空店鋪，沒有空店鋪就重設倒數。不連續移動，不加 isovist。Vendor (Idle) 世代＝新時也呼叫這個方法","params":{"MOVE_MIN_TICK":{"value":1,"unit":"tick"},"MOVE_MAX_TICK":{"value":4,"unit":"tick","note":"倒數重設值隨機 MOVE_MIN~MOVE_MAX"}},"impl":"agents/vendorNew.js#relocationJudgement","status":"implemented","implRefs":["agents/vendorNew.js#relocationJudgement"]},"siteFertility":{"desc":"空店鋪搬遷權重 weight＝heat（店鋪格 touristTrailHeat+residentTrailHeat 總和，不衰減）＋ corridorFrontage×FRONTAGE_SCALE（建築先天條件）＋ visFertility（shop.visibility：未達 VIS_LOW 為 0、一般 VIS_FERTILITY_MID、超過 VIS_HIGH 為 VIS_FERTILITY_HIGH，固定值）＋ FERTILITY_BASE_WEIGHT（避免全 0 死鎖）","params":{"FERTILITY_BASE_WEIGHT":{"value":1,"unit":"weight","note":"底線權重"},"FRONTAGE_SCALE":{"value":3,"unit":"weight/frontage","note":"corridorFrontage(0~1)換算倍率，自訂、可覆寫"},"VIS_FERTILITY_MID":{"value":1,"unit":"weight","note":"可見度一般；自訂值，可覆寫"},"VIS_FERTILITY_HIGH":{"value":2,"unit":"weight","note":"可見度顯眼；隱蔽為 0；自訂值，可覆寫"}},"reads":["Cell.corridorFrontage","Cell.visibility"],"impl":"agents/vendorNew.js#visFertility | agents/vendorNew.js#shopFertility | agents/vendorNew.js#pickFertileBlank","status":"implemented","implRefs":["agents/vendorNew.js#visFertility","agents/vendorNew.js#shopFertility","agents/vendorNew.js#pickFertileBlank"]},"stepTick":{"desc":"逐輪：updateHeatHistory → idleJudgement → relocationJudgement","impl":"agents/vendorNew.js#stepTick","status":"implemented","implRefs":["agents/vendorNew.js#stepTick"]},"initStall":{"desc":"moveTimer／visitHist／zeroStreak 歸零","writes":["VendorNew.popularity","VendorNew.coldStreak"],"impl":"agents/vendorNew.js#initStall","status":"implemented","implRefs":["agents/vendorNew.js#initStall"]},"heatOf":{"desc":"讀 popularity","impl":"agents/vendorNew.js#heatOf","status":"implemented","implRefs":["agents/vendorNew.js#heatOf"]},"updateHeatHistory":{"desc":"更新 visitHist／zeroStreak","impl":"agents/vendorNew.js#updateHeatHistory","status":"implemented","implRefs":["agents/vendorNew.js#updateHeatHistory"]}}},{"id":"VendorOld","extends":"Vendor","label":"正常營業中的老攤商，位置永久固定","attributes":{"fixed":{"desc":"沒有關門判定，位置也永久固定","variants":[{"adjective":"一間屹立不搖、永遠不會倒的老店","when":"always","effect":["Fixed Rule：不移動、無搬遷判定"]}],"status":"implemented"}},"rules":{"fixed":{"desc":"恆常固定：永久不移動、無任何搬遷判定。Vendor (Idle) 世代＝老時邏輯等同這條（目前不會被觸發）","impl":"agents/vendorOld.js#stepTick（空實作）","status":"implemented","implRefs":["agents/vendorOld.js#stepTick"]}}},{"id":"Cell","label":"市場網格本身；World.cellSpace 與 cellType 同尺寸，每個攤位格各存一份屬性物件，其餘格型存 null","attributes":{"corridorFrontage":{"desc":"這一格 4 個方向裡臨走道／入口格的邊數比例（0~1）；位置固定，不隨進駐攤販或搬遷改變。店鋪彙總＝所屬格子平均值，存 shop.corridorFrontage","formula":"aisleEdges / 4","variants":[{"adjective":"一個緊臨走道的店鋪","when":"corridorFrontage 高","effect":["siteFertility 先天權重高，沒用過也容易被選中"]},{"adjective":"一個被夾在店鋪之間的格子","when":"corridorFrontage 低","effect":["siteFertility 先天權重低，得靠行為痕跡累積"]}],"impl":"agents/cell.js#buildCellSpace | agents/cell.js#frontageOf | agents/cell.js#shopFrontage","status":"implemented","implRefs":["agents/cell.js#buildCellSpace","agents/cell.js#frontageOf","agents/cell.js#shopFrontage"]},"mobility":{"desc":"可變動性：這一格（Block）開放或封閉、整個東西會不會動；定義的是 Block，不是攤販本身。走道格由時間、店鋪營業狀態與 occupiedBy 推得（擺椅時段內 occupiedBy 裡至少有一家有營業的店＝Chair_Mobility，否則完全開放）","candidates":["完全開放","半開放","封閉","流動攤車","Chair_Mobility"],"variants":[{"adjective":"一個開放的走道格（完全開放）","when":"擺椅時段外，或 occupiedBy 裡沒有營業中的店","effect":["passableFor 照走道處理，可通行"]},{"adjective":"一個被店家擺了椅子的走道格（Chair_Mobility）","when":"擺椅時段內，occupiedBy 裡至少有一家有營業的店","effect":["passableFor 照走道處理，行人照常通過","Human.chairSlowdown：行人走進去多停 CHAIR_SLOW_SEC","Human.chairTieBreak：距離一樣近時優先走沒椅子的格子"]}],"source":"2026-10-02 課堂筆記（以可變動性為單一軸線往下細分）","replaces":"STALL_STRUCTURE（移動攤販／半開放／鐵門封閉）","status":"implemented","impl":"agents/cell.js#hasChair","implRefs":["agents/cell.js#hasChair"]},"occupiedBy":{"desc":"有資格擺椅的店鋪 code 清單（走道格：兩家共用的用餐區可有兩個；店鋪自己 zone 是用餐區的攤位格：＝自己的 code，用餐區一律有椅子），QGIS 標定（ERA_DATA.cells['r,c'].occupiedBy，值是 display_code），固定不變、不隨模擬改寫；只有這一份。椅子是否擺出看時間與店鋪營業狀態（見 Vendor.chairRule）","source":"使用者 2026-10-04 在 QGIS aisle.occupied_by 標定 33 格，經 adapter_era_data.py 輸出到 ERA_DATA","impl":"agents/cell.js#buildCellSpace","status":"implemented","implRefs":["agents/cell.js#buildCellSpace"]},"noEnter":{"desc":"攤位格客人不進入：zone（SIM_ERA＝2026 的 ERA_DATA zone）是桌面空間、工作桌面混合、工作設備區為真；位置固定，工作空間、用餐區為假","variants":[{"adjective":"一個桌面或設備的格子","when":"noEnter 為真","effect":["Human.passableFor 一律不可通行","客人靠 Human.visitRule 站在外面到訪"]},{"adjective":"一個可站人的店鋪格","when":"noEnter 為假（工作空間、用餐區）","effect":["Human.passableFor 依興趣目標狀態通行"]}],"impl":"agents/cell.js#buildCellSpace | agents/cell.js#noEnter","status":"implemented","implRefs":["agents/cell.js#buildCellSpace","agents/cell.js#noEnter"]},"passCost":{"desc":"行人走進這格的成本，由 mobility 推得：完全開放＝PASS_COST_OPEN、Chair_Mobility＝PASS_COST_CHAIR；牆／設施等不可通行格不算成本（由 Human.passableFor 擋）。隨 mobility 變動，擺椅時段內變高、收攤後回到 1","variants":[{"adjective":"一個好走的走道格","when":"passCost 低（完全開放）","effect":["Human.passCostPath 照單位成本算，行人不會特地繞開"]},{"adjective":"一個難走的走道格","when":"passCost 高（Chair_Mobility）","effect":["Human.chairSlowdown 讓人多停","Human.passCostPath 讓 Resident 的 BFS 在繞路不吃虧時改走別條"]}],"reads":["Cell.mobility"],"impl":"agents/cell.js#passCost","status":"implemented","implRefs":["agents/cell.js#passCost"]},"density":{"desc":"這格周圍 DENSITY_RADIUS 格（方形範圍）內、不含自己的行人數（Tourist＋Resident 合計），每步依場上行人位置重算，不累積、不存歷史（累積的是 touristTrailHeat／residentTrailHeat）","variants":[{"adjective":"一個冷清的格子","when":"density < CROWD_THRESHOLD","effect":["Human.crowdRule 不介入"]},{"adjective":"一個擁擠的格子","when":"CROWD_THRESHOLD ≤ density ≤ JAM_THRESHOLD","effect":["Human.crowdRule 讓行人在這格多停 CROWD_SLOW_SEC"]},{"adjective":"一個塞住的格子","when":"density > JAM_THRESHOLD","effect":["Human.crowdRule 不再多停，每步 ticksSinceProgress 額外加 JAM_GIVEUP_EXTRA，更快放棄離場"]}],"impl":"agents/cell.js#refreshDensity | agents/cell.js#densityAt","status":"implemented","implRefs":["agents/cell.js#refreshDensity","agents/cell.js#densityAt"]},"visibility":{"desc":"0～1：能看到這格的走道格數，除以全圖最大值；阻擋判定同 Tourist.isVisible（牆、設施、建物、任何攤位格擋視線，距離上限同監測範圍）；位置固定，阻擋物變了才重算。店鋪彙總＝所屬格子平均值，存 shop.visibility，設定時算一次。與 corridorFrontage 不同：後者只數臨走道的邊，這個數實際看得到的範圍","params":{"VIS_LOW":{"value":0.2,"unit":"0~1","note":"低於 → 隱蔽；自訂值，可覆寫"},"VIS_HIGH":{"value":0.4,"unit":"0~1","note":"高於 → 顯眼；自訂值，可覆寫"}},"variants":[{"adjective":"一個藏在深處的店鋪","when":"visibility < VIS_LOW","effect":["siteFertility 可見度項為 0","Tourist.visBonus 為 0"]},{"adjective":"一個普通能被看見的店鋪","when":"VIS_LOW ≤ visibility ≤ VIS_HIGH","effect":["siteFertility 給 VIS_FERTILITY_MID","Tourist.visBonus 為 0"]},{"adjective":"一個顯眼的店鋪","when":"visibility > VIS_HIGH","effect":["Tourist.visBonus 加分（固定值）","siteFertility 給 VIS_FERTILITY_HIGH（固定值）"]}],"impl":"agents/cell.js#buildVisibility | agents/cell.js#shopVisibility","status":"implemented","implRefs":["agents/cell.js#buildVisibility","agents/cell.js#shopVisibility"]},"orientation":{"desc":"方向性","source":"2026-10-02 課堂筆記","status":"planned"}},"rules":{"note":"Cell 不定義自己的規則，只提供量化值；使用它的判斷邏輯放對應 agent 的 Rule（例如 VendorNew.siteFertility）"}}],"refs":{"agents/tourist.js#passableFor":{"file":"agents/tourist.js","fn":"passableFor","note":"","line":14,"code":"  // 通行限制：牆/設施不可過；攤位格只有等於興趣目標狀態才能踏入，否則視同牆。\n  // 狀態查詢走 s.shop.state（20260824 使用者需求(1)：同編號＝同店鋪，狀態記在店鋪上）。\n  passableFor(r, c) {\n    if (!World.passable(r, c)) return false;\n    const t = World.cellType[r][c];\n    if (t !== 'stallslot') return true;\n    const s = World.stallAtRC[r + ',' + c];\n    return s.shop.state === this.interestState && !Cell.noEnter(r, c); // 桌面／設備格不進（Passability Rule）\n  },","usedBy":["Human.passableFor"]},"agents/resident.js#passableFor":{"file":"agents/resident.js","fn":"passableFor","note":"","line":13,"code":"  // 狀態查詢走 s.shop.state（20260824 使用者需求(1)：同編號＝同店鋪，狀態記在店鋪上）。\n  passableFor(r, c) {\n    if (!World.passable(r, c)) return false;\n    const t = World.cellType[r][c];\n    if (t !== 'stallslot') return true;\n    const s = World.stallAtRC[r + ',' + c];\n    return s.shop.state === this.interestState && !Cell.noEnter(r, c); // 桌面／設備格不進（Passability Rule）\n  },","usedBy":["Human.passableFor"]},"agents/tourist.js#spawnExpected":{"file":"agents/tourist.js","fn":"spawnExpected","note":"","line":202,"code":"  // 生成規則：由入口格產生，數量隨興趣目標類型的攤位數增加（實際換算在 index.html 的 spawnPedestriansContinuous）。\n  spawnExpected(expected) {\n    if (World.entryCells.length === 0) return;\n    let n = Math.floor(expected);\n    if (Math.random() < (expected - n)) n++;\n    for (let i = 0; i < n; i++) {\n      const e = World.entryCells[Math.floor(Math.random() * World.entryCells.length)];\n      // faceDr/faceDc：純視覺用的朝向（ISO metaball 畫圖偏向用，見 20260914 grilling Q4）——只記最後一次\n      // 移動方向，不是規格 Rule，isVisible() 找目標/跟隨的判定邏輯不受這個影響，維持文件寫的360度全向。\n      this.pedestrians.push({ row: e.r, col: e.c, visited: new Set(), ticksSinceProgress: 0, faceDr: 1, faceDc: 0 });\n    }\n  },","usedBy":["Human.spawnExpected"]},"agents/resident.js#spawnExpected":{"file":"agents/resident.js","fn":"spawnExpected","note":"","line":91,"code":"  spawnExpected(expected) {\n    if (World.entryCells.length === 0) return;\n    let n = Math.floor(expected);\n    if (Math.random() < (expected - n)) n++;\n    for (let i = 0; i < n; i++) {\n      const e = World.entryCells[Math.floor(Math.random() * World.entryCells.length)];\n      this.pedestrians.push({ row: e.r, col: e.c, visited: new Set(), ticksSinceProgress: 0 });\n    }\n  },","usedBy":["Human.spawnExpected"]},"index.html#timeBandMult":{"file":"index.html","fn":"timeBandMult","note":"","line":980,"code":"// 時間波段倍率 [Tourist, Resident]（Spawn Rule 時間波段，agent_setting.md）：查 TIME_BANDS，區間外（休市）＝0，不正規化。\nfunction timeBandMult() {\n  const h = Cell.hourNow(), b = CONFIG.params.TIME_BANDS.find(([a, e]) => h >= a && h < e);\n  return b ? [b[3], b[2]] : [0, 0]; // TIME_BANDS 列：[起, 終, Resident, Tourist]\n}","usedBy":["Human.spawnExpected"]},"agents/tourist.js#move":{"file":"agents/tourist.js","fn":"move","note":"","line":215,"code":"  // 演算法第5點 touristStep：可見未訪目標(熱度加權) → 看不到就找可見同伴(跟隨) → 都沒有就隨機走。\n  // 使用者需求(2)：站在店鋪格子裡、沒有下一個可見目標時，不跟同伴/不亂走，直接走最近走道出去（逛完就走，不閒晃）。\n  // 結束規則：到訪一攤不會消失，繼續逛，直到放棄計時器(第7點，ticksSinceProgress)超過門檻才離場（多站購物）。\n  move(trailHeat) {\n    const stillAlive = [];\n    for (const p of this.pedestrians) {\n      if (!Cell.tickPause(p)) this.step(p, trailHeat); // 停留中（走慢／坐下）這一步不移動\n      if (!p.sitShop) p.ticksSinceProgress++; // 演算法第7點：離上次成功到訪過了幾步（＝幾秒）；走慢／擁擠的停留照常累加，坐著不累加\n      if (p.ticksSinceProgress < this.giveupSec) stillAlive.push(p);\n      else Cell.release(p);\n    }\n    this.pedestrians = stillAlive;\n  },","usedBy":["Human.giveupRule","Human.chairSlowdown","Human.crowdRule","Human.chairSeating","Tourist.move"]},"agents/resident.js#move":{"file":"agents/resident.js","fn":"move","note":"（inline）","line":101,"code":"  // 演算法第7點 residentStep：targets 為空(全逛完/沒有營業中old) → 隨機走；否則 BFS 場，走場值最小的鄰格，\n  // 場不可達時退回隨機鄰格。使用者需求(2)：站在店鋪格子裡、沒有下一個未訪目標時，直接走最近走道出去，不亂走閒晃。\n  // 結束規則同 Tourist：多站購物，直到放棄計時器超過門檻才離場。\n  move(trailHeat) {\n    const stillAlive = [];\n    for (const p of this.pedestrians) {\n      if (!Cell.tickPause(p)) this.step(p, trailHeat); // 停留中（走慢／坐下）這一步不移動\n      if (!p.sitShop) p.ticksSinceProgress++; // 坐著不算沒進展（見 Chair Seating Rule）\n      if (p.ticksSinceProgress < this.giveupSec) stillAlive.push(p);\n      else Cell.release(p);\n    }\n    this.pedestrians = stillAlive;\n  },","usedBy":["Human.giveupRule","Human.chairSlowdown","Human.crowdRule","Human.chairSeating","Resident.move"]},"agents/tourist.js#exitStep":{"file":"agents/tourist.js","fn":"exitStep","note":"","line":198,"code":"  exitStep(p) {\n    return this.bestStepByField(p, this.bfsFieldToAisle(p));\n  },","usedBy":["Human.exitStep"]},"agents/resident.js#exitStep":{"file":"agents/resident.js","fn":"exitStep","note":"","line":85,"code":"  // 使用者需求(2)：逛完店鋪（或暫時找不到下一個未訪目標）時不留在店內閒晃，直接找最近走道走出去。\n  // targets 換成所有走道格（開場算好存在 World.aisleCells，不重掃），共用同一套 bfsFieldFromTargets。\n  exitStep(p) {\n    return this.bestStepByField(p, this.bfsFieldFromTargets(World.aisleCells, p));\n  },","usedBy":["Human.exitStep"]},"agents/cell.js#shopsReach":{"file":"agents/cell.js","fn":"shopsReach","note":"","line":31,"code":"  // Visit Rule：這格能「到訪」的店鋪＝站的位置、上下左右相鄰的攤位格所屬店鋪（站在店面前），加上擺椅時段內椅子延伸出來的店面（occupiedBy）。\n  shopsReach(r, c) {\n    const out = [];\n    for (const [dr, dc] of [[0, 0], ...World.DIRS4]) {\n      const s = World.stallAtRC[(r + dr) + ',' + (c + dc)];\n      if (s && !out.includes(s.shop)) out.push(s.shop);\n    }\n    const cs = World.cellSpace[r][c];\n    if (cs && cs.occupiedBy && this.chairsOut())\n      for (const code of cs.occupiedBy) { const sh = World.shopByCode[code]; if (sh && !out.includes(sh)) out.push(sh); }\n    return out;\n  },","usedBy":["Human.visitRule"]},"agents/tourist.js#step":{"file":"agents/tourist.js","fn":"step","note":"","line":229,"code":"  step(p, trailHeat) {\n      const target = this.findVisibleTarget(p, trailHeat);\n      let next;\n      if (target) {\n        next = this.greedyStepToward(p, target.row, target.col);\n      } else if (World.cellType[p.row][p.col] === 'stallslot') {\n        next = this.exitStep(p);\n      } else {\n        const peer = this.findVisiblePeer(p);\n        next = peer ? this.greedyStepToward(p, peer.row, peer.col) : this.randomStep(p);\n      }\n      if (next) {\n        const dr = next[0] - p.row, dc = next[1] - p.col; // 記朝向（純視覺，見 spawnExpected 註解）\n        if (dr !== 0 || dc !== 0) { p.faceDr = dr; p.faceDc = dc; }\n        p.row = next[0]; p.col = next[1];\n        Cell.slowIfChair(p); // Chair Slowdown Rule\n        Cell.crowdReact(p); // Crowd Rule\n      }\n\n      trailHeat[p.row][p.col] += TRAIL_STEP_ADD * heatW; // 不衰減、不封頂，見 simulator_setting.md\n\n      for (const shop of Cell.shopsReach(p.row, p.col)) { // Visit Rule：站在店面前／店面延伸的椅子格也算到訪\n        if (shop.state !== this.interestState || p.visited.has(shop.code)) continue;\n        shop._visitTick = (shop._visitTick || 0) + visitW; // 人氣熱度記在店鋪上，供 VendorNew 用\n        p.visited.add(shop.code);\n        p.ticksSinceProgress = 0;\n        Cell.trySit(p, shop); // Chair Seating Rule\n        break; // 一步最多到訪一家（同步驟再多家，下一步照樣到訪）\n      }\n  },","usedBy":["Human.visitRule"]},"agents/resident.js#step":{"file":"agents/resident.js","fn":"step","note":"","line":115,"code":"  step(p, trailHeat) {\n      const targets = World.stalls.filter(s => s.shop.state === this.interestState && !p.visited.has(s.shop.code));\n      let next = null;\n      if (targets.length > 0) {\n        next = this.bestStepByField(p, this.bfsFieldFromTargets(targets, p));\n      }\n      if (!next && World.cellType[p.row][p.col] === 'stallslot') next = this.exitStep(p);\n      if (!next) next = this.randomStep(p); // 沒有未訪目標／目標暫時不可達的備援\n      if (next) { p.row = next[0]; p.col = next[1]; Cell.slowIfChair(p); Cell.crowdReact(p); } // Chair Slowdown Rule、Crowd Rule\n\n      trailHeat[p.row][p.col] += TRAIL_STEP_ADD * heatW; // 不衰減、不封頂，見 simulator_setting.md\n\n      for (const shop of Cell.shopsReach(p.row, p.col)) { // Visit Rule：站在店面前／店面延伸的椅子格也算到訪\n        if (shop.state !== this.interestState || p.visited.has(shop.code)) continue;\n        shop._visitTick = (shop._visitTick || 0) + visitW; // 人氣熱度記在店鋪上，供 VendorOld/VendorNew 用\n        p.visited.add(shop.code);\n        p.ticksSinceProgress = 0;\n        Cell.trySit(p, shop); // Chair Seating Rule\n        break;\n      }\n  },","usedBy":["Human.visitRule"]},"agents/cell.js#slowIfChair":{"file":"agents/cell.js","fn":"slowIfChair","note":"","line":84,"code":"  slowIfChair(p) { if (this.hasChair(p.row, p.col)) p.pause = CONFIG.params.CHAIR_SLOW_SEC; },","usedBy":["Human.chairSlowdown"]},"agents/cell.js#tickPause":{"file":"agents/cell.js","fn":"tickPause","note":"","line":76,"code":"  // 停留（Chair Slowdown：走進有椅子的格子多停 CHAIR_SLOW_SEC；Chair Seating：坐下停 SIT_SEC）。\n  // 行人記 p.pause（還要停幾步＝幾秒）、p.sitShop（坐下的店鋪，停完還座位）。Tourist／Resident 的 move() 共用。\n  tickPause(p) { // 停留中 → true（這一步不移動）；停完那一刻還座位\n    if (!(p.pause > 0)) return false;\n    if (--p.pause === 0) this.release(p);\n    return true;\n  },","usedBy":["Human.chairSlowdown"]},"agents/cell.js#preferNoChair":{"file":"agents/cell.js","fn":"preferNoChair","note":"","line":133,"code":"  // Chair Avoidance Rule：距離一樣近的候選格裡，優先選沒有椅子的；全都有椅子就維持原樣。\n  preferNoChair(cands) {\n    const free = cands.filter(([r, c]) => !this.hasChair(r, c));\n    return free.length ? free : cands;\n  },","usedBy":["Human.chairTieBreak"]},"agents/tourist.js#greedyStepToward":{"file":"agents/tourist.js","fn":"greedyStepToward","note":"","line":120,"code":"  // 演算法第4點 greedyStepToward：4方向貪婪，最小曼哈頓距離，同分隨機。\n  greedyStepToward(p, targetRow, targetCol) {\n    let best = Infinity, cands = [];\n    for (const [dr, dc] of World.DIRS4) {\n      const nr = p.row + dr, nc = p.col + dc;\n      if (!this.passableFor(nr, nc)) continue;\n      const d = Math.abs(nr - targetRow) + Math.abs(nc - targetCol);\n      if (d < best) { best = d; cands = [[nr, nc]]; }\n      else if (d === best) cands.push([nr, nc]);\n    }\n    cands = Cell.preferNoChair(cands); // Chair Avoidance Rule：距離一樣近時優先走沒椅子的格子\n    return cands.length ? cands[Math.floor(Math.random() * cands.length)] : null;\n  },","usedBy":["Human.chairTieBreak"]},"agents/tourist.js#bestStepByField":{"file":"agents/tourist.js","fn":"bestStepByField","note":"","line":185,"code":"  bestStepByField(p, field) {\n    if (this.fieldGet(field, p.row, p.col) === Infinity) return null;\n    let best = Infinity, cands = [];\n    for (const [dr, dc] of World.DIRS4) {\n      const nr = p.row + dr, nc = p.col + dc;\n      if (!this.passableFor(nr, nc)) continue;\n      const v = this.fieldGet(field, nr, nc);\n      if (v < best) { best = v; cands = [[nr, nc]]; }\n      else if (v === best) cands.push([nr, nc]);\n    }\n    cands = Cell.preferNoChair(cands); // Chair Avoidance Rule\n    return cands.length ? cands[Math.floor(Math.random() * cands.length)] : null;\n  },","usedBy":["Human.chairTieBreak"]},"agents/resident.js#bestStepByField":{"file":"agents/resident.js","fn":"bestStepByField","note":"","line":71,"code":"  // 走場值最小的可通行鄰格，同分隨機；bfsFieldFromTargets 產出的 field 都用這個取下一步。\n  bestStepByField(p, field) {\n    if (this.fieldGet(field, p.row, p.col) === Infinity) return null;\n    let best = Infinity, cands = [];\n    for (const [dr, dc] of World.DIRS4) {\n      const nr = p.row + dr, nc = p.col + dc;\n      if (!this.passableFor(nr, nc)) continue;\n      const v = this.fieldGet(field, nr, nc);\n      if (v < best) { best = v; cands = [[nr, nc]]; }\n      else if (v === best) cands.push([nr, nc]);\n    }\n    cands = Cell.preferNoChair(cands); // Chair Avoidance Rule：距離一樣近時優先走沒椅子的格子\n    return cands.length ? cands[Math.floor(Math.random() * cands.length)] : null;\n  },","usedBy":["Human.chairTieBreak"]},"agents/cell.js#passCost":{"file":"agents/cell.js","fn":"passCost","note":"","line":90,"code":"  // Attribute：passCost —— 走進這格的成本，由 mobility 推得（Pass Cost Attribute）：擺椅＝PASS_COST_CHAIR，其餘＝PASS_COST_OPEN。\n  // 不可通行格不算成本（passableFor 擋）；Resident 的 bfsFieldFromTargets 用它做加權最短路徑。\n  passCost(r, c) { return this.hasChair(r, c) ? CONFIG.params.PASS_COST_CHAIR : CONFIG.params.PASS_COST_OPEN; },","usedBy":["Human.passCostPath","Cell.passCost"]},"agents/resident.js#bfsFieldFromTargets":{"file":"agents/resident.js","fn":"bfsFieldFromTargets","note":"","line":22,"code":"  // 演算法第6點 bfsFieldFromTargets：多來源 BFS，起點＝targets 全部同時展開，field[r][c]＝走到最近一個目標的實際步數。\n  // 效能（2026-09-14，見 cellmachine-grid-system-design 記憶）：field 只會被 bestStepByField 拿來查\n  // stopAt 那一格跟它的4鄰格，BFS 本身「一格的距離值一旦指定就不會再變」，所以搜到 stopAt 那格當下就能停，\n  // 跟跑完全圖的結果完全等價，不是打折的近似值——把 O(全圖格數) 降成 O(離最近目標的實際步數)。\n  // dist 也從整張網格大小的陣列改成 Map（只存真的算過的格子），避免每次呼叫都配置一個跟地圖同大小的陣列。\n  // Pass Cost Rule（agent_setting.md）：路徑成本＝每格 Cell.passCost 加總，不再是單位步數。成本只有 1／2 這種小整數，\n  // 用 Dial 分桶（buckets[累計成本]）取代 heap。反向展開：鄰格走進 (r,c) 要付 (r,c) 的成本，所以 nd＝d＋passCost(r,c)。\n  // 停止條件：一桶（同成本）一定要整桶展開完才停——同桶裡成本較低的格子（1）可能把 stopAt 鄰格的值壓低（stopAt 若是 2），\n  // 鄰格值才確定；而且要在 stopAt 展開之後（鄰格拿到值之後）停，理由同單位成本版。\n  bfsFieldFromTargets(targets, stopAt) {\n    const dist = new Map();\n    const key = (r, c) => r * World.COLS + c;\n    const buckets = [[]];\n    for (const s of targets) { const k = key(s.row, s.col); if (!dist.has(k)) { dist.set(k, 0); buckets[0].push([s.row, s.col]); } }\n    for (let d = 0; d < buckets.length; d++) {\n      let found = false;\n      for (const [r, c] of buckets[d] || []) {\n        if (dist.get(key(r, c)) !== d) continue; // 已被更便宜的路徑更新過\n        const nd = d + Cell.passCost(r, c);\n        for (const [dr, dc] of World.DIRS4) {\n          const nr = r + dr, nc = c + dc;\n          if (!this.passableFor(nr, nc)) continue;\n          const nk = key(nr, nc), old = dist.get(nk);\n          if (old !== undefined && old <= nd) continue;\n          dist.set(nk, nd);\n          (buckets[nd] || (buckets[nd] = [])).push([nr, nc]);\n        }\n        if (stopAt && r === stopAt.row && c === stopAt.col) found = true;\n      }\n      if (found) break;\n    }\n    return dist;\n  },","usedBy":["Human.passCostPath","Resident.bfsFieldFromTargets"]},"agents/cell.js#crowdReact":{"file":"agents/cell.js","fn":"crowdReact","note":"","line":107,"code":"  // Crowd Rule：行人落地後依所在格 density 反應。達 CROWD_THRESHOLD 且未超過 JAM_THRESHOLD → 多停 CROWD_SLOW_SEC；超過 JAM_THRESHOLD → 放棄計時器多加 JAM_GIVEUP_EXTRA。\n  crowdReact(p) {\n    const d = this.densityAt(p.row, p.col), P = CONFIG.params;\n    if (d > P.JAM_THRESHOLD) p.ticksSinceProgress += P.JAM_GIVEUP_EXTRA;\n    else if (d >= P.CROWD_THRESHOLD) p.pause = Math.max(p.pause || 0, P.CROWD_SLOW_SEC);\n  },","usedBy":["Human.crowdRule"]},"agents/cell.js#refreshDensity":{"file":"agents/cell.js","fn":"refreshDensity","note":"","line":97,"code":"  refreshDensity() {\n    const R = CONFIG.params.DENSITY_RADIUS, m = (this.dens = new Map());\n    for (const C of [Tourist, Resident]) for (const p of C.pedestrians)\n      for (let r = p.row - R; r <= p.row + R; r++) for (let c = p.col - R; c <= p.col + R; c++) {\n        if (c < 0 || c >= World.COLS) continue; // 避免 key 繞到上一列\n        const k = r * World.COLS + c; m.set(k, (m.get(k) || 0) + 1);\n      }\n  },","usedBy":["Human.crowdRule","Cell.density"]},"agents/cell.js#trySit":{"file":"agents/cell.js","fn":"trySit","note":"","line":85,"code":"  trySit(p, shop) { // Chair Seating Rule：到訪當下有空位 → 坐下；滿座照常算到訪、不坐\n    if (!this.hasSeat(shop)) return;\n    shop.seatsTaken++; p.sitShop = shop; p.pause = CONFIG.params.SIT_SEC;\n  },","usedBy":["Human.chairSeating","Vendor.seatsTaken"]},"agents/cell.js#hasSeat":{"file":"agents/cell.js","fn":"hasSeat","note":"","line":73,"code":"  // 這家店現在還有空位（擺椅時段內、營業、沒坐滿）：Chair Seating Rule（坐下）與 Tourist 的 chairBonus（吸引）共用。不看用餐時間。\n  hasSeat(shop) { return shop.seatsTaken < this.seatsOf(shop); },","usedBy":["Human.chairSeating"]},"agents/cell.js#release":{"file":"agents/cell.js","fn":"release","note":"","line":83,"code":"  release(p) { if (p.sitShop) { p.sitShop.seatsTaken--; p.sitShop = null; } }, // 停完或離場都要還座位","usedBy":["Human.chairSeating"]},"agents/tourist.js#isVisible":{"file":"agents/tourist.js","fn":"isVisible","note":"","line":49,"code":"  isVisible(r0, c0, r1, c1) {\n    if (!this.visId) this.visId = new Int32Array(World.ROWS * World.COLS).fill(-1);\n    const k0 = r0 * World.COLS + c0, k1 = r1 * World.COLS + c1;\n    let i0 = this.visId[k0]; if (i0 < 0) i0 = this.visId[k0] = this.visNext++;\n    let i1 = this.visId[k1]; if (i1 < 0) i1 = this.visId[k1] = this.visNext++;\n    if (i0 >= this.VIS_CAP || i1 >= this.VIS_CAP) return this.computeVisible(r0, c0, r1, c1);\n    const row = this.visRows[i0] || (this.visRows[i0] = new Uint8Array(this.VIS_CAP));\n    let v = row[i1];\n    if (!v) { v = this.computeVisible(r0, c0, r1, c1) ? 2 : 1; row[i1] = v; }\n    return v === 2;\n  },","usedBy":["Tourist.isVisible"]},"agents/tourist.js#heatBonus":{"file":"agents/tourist.js","fn":"heatBonus","note":"","line":79,"code":"  // Attribute 熱度偏好：多目標時比「距離−熱度加成」，非純距離。門檻同 simulator_setting.md 軌跡熱力三級門檻 1/10/25。\n  heatBonus(h) {\n    const t = CONFIG.params.HEAT_BONUS_TIERS.E.find(([min]) => h >= min); // E人分支，I人見 tourist.json\n    return t ? t[1] : 0;\n  },","usedBy":["Tourist.heatBonus"]},"agents/tourist.js#chairBonus":{"file":"agents/tourist.js","fn":"chairBonus","note":"","line":85,"code":"  // Target Scoring 的椅子加分（Tourist 專屬）：該店有擺出椅子、還有空位 → 分數減 CHAIR_ATTRACT_BONUS（感覺比較近）；滿座或沒擺椅子為 0。\n  chairBonus(shop) { return Cell.hasSeat(shop) ? CONFIG.params.CHAIR_ATTRACT_BONUS : 0; },","usedBy":["Tourist.chairBonus"]},"agents/tourist.js#visBonus":{"file":"agents/tourist.js","fn":"visBonus","note":"","line":88,"code":"  // Target Scoring 的可見度加分（Tourist 專屬）：店鋪 visibility 超過 VIS_HIGH（顯眼）→ 分數減 VIS_ATTRACT_BONUS，固定值；其餘 0。\n  visBonus(shop) { return shop.visibility > CONFIG.params.VIS_HIGH ? CONFIG.params.VIS_ATTRACT_BONUS : 0; },","usedBy":["Tourist.visBonus"]},"agents/tourist.js#findVisibleTarget":{"file":"agents/tourist.js","fn":"findVisibleTarget","note":"","line":91,"code":"  // 演算法第2點 findVisibleTarget：看得到、還沒去過的同類型目標裡，score(距離−熱度加成)最小者，同分隨機。\n  // 到訪判定以店鋪（s.shop.code）為單位：同店鋪的其他格子不會被當成沒去過的新目標。\n  findVisibleTarget(p, trailHeat) {\n    let best = Infinity, cands = [];\n    for (const s of this.visibleStalls(p.row, p.col)) {\n      if (s.shop.state !== this.interestState || p.visited.has(s.shop.code)) continue;\n      const dist = Math.hypot(s.row - p.row, s.col - p.col);\n      const score = dist - this.heatBonus(trailHeat[s.row][s.col]) - this.chairBonus(s.shop) - this.visBonus(s.shop);\n      if (score < best) { best = score; cands = [s]; }\n      else if (score === best) cands.push(s);\n    }\n    return cands.length ? cands[Math.floor(Math.random() * cands.length)] : null;\n  },","usedBy":["Tourist.findVisibleTarget"]},"agents/tourist.js#findVisiblePeer":{"file":"agents/tourist.js","fn":"findVisiblePeer","note":"","line":105,"code":"  // 演算法第3點 findVisiblePeer：看不到目標時的跟隨 fallback，找看得到的其他 Tourist（純距離，不加熱度）。\n  // 來源：視野受限時的盲從跟隨是群體移動的標準現象（Social Force Model 及後續視野受限跟隨研究）。\n  findVisiblePeer(p) {\n    let best = Infinity, cands = [];\n    for (const other of this.pedestrians) {\n      if (other === p) continue;\n      const dist = Math.hypot(other.row - p.row, other.col - p.col);\n      if (dist > best) continue; // 比目前最近的還遠就不用查視線（結果相同，只是少查）\n      if (!this.isVisible(p.row, p.col, other.row, other.col)) continue;\n      if (dist < best) { best = dist; cands = [other]; }\n      else if (dist === best) cands.push(other);\n    }\n    return cands.length ? cands[Math.floor(Math.random() * cands.length)] : null;\n  },","usedBy":["Tourist.findVisiblePeer"]},"agents/cell.js#seatsOf":{"file":"agents/cell.js","fn":"seatsOf","note":"","line":70,"code":"  // 座位數＝這家店現在擺出的椅子數（一格一張）；時段外或沒營業為 0。chairCells 在 computeStallGroups 數一次。\n  seatsOf(shop) { return this.chairsOut() && this.isOpen(shop) ? shop.chairCells : 0; },","usedBy":["Vendor.seatsTaken"]},"agents/cell.js#chairsOut":{"file":"agents/cell.js","fn":"chairsOut","note":"","line":59,"code":"  chairsOut() { return this.hourNow() >= CONFIG.params.CHAIR_START_HOUR && this.hourNow() < CONFIG.params.CHAIR_END_HOUR; },","usedBy":["Vendor.chairRule"]},"agents/cell.js#isOpen":{"file":"agents/cell.js","fn":"isOpen","note":"","line":60,"code":"  isOpen(shop) { return !!shop && (shop.state === 'new' || shop.state === 'old'); }, // 「營業」＝new 或 old","usedBy":["Vendor.chairRule"]},"agents/cell.js#chairCount":{"file":"agents/cell.js","fn":"chairCount","note":"","line":62,"code":"  // 這格現在有幾張椅子：擺椅時段內，occupiedBy 裡有營業的店各一張。\n  chairCount(r, c) {\n    const cs = World.cellSpace[r][c];\n    if (!cs || !cs.occupiedBy || !this.chairsOut()) return 0;\n    return cs.occupiedBy.filter(code => this.isOpen(World.shopByCode[code])).length;\n  },","usedBy":["Vendor.chairRule"]},"agents/vendorIdle.js#stepTick":{"file":"agents/vendorIdle.js","fn":"stepTick","note":"","line":7,"code":"  stepTick() {\n    World.shops.filter(s => s.state === 'new_unused').forEach(s => {\n      if (Math.random() < this.REOPEN_PROB) {\n        s.state = 'new';\n        VendorNew.initStall(s); // 重開＝新攤販進駐，人氣/搬遷倒數歸零重算\n        return;\n      }\n      VendorNew.relocationJudgement(s); // 沒重開，跟 VendorNew 共用搬遷邏輯\n    });\n    // old_unused：無 Rule，什麼都不做。\n  }","usedBy":["VendorIdle.reopen"]},"agents/vendorNew.js#idleJudgement":{"file":"agents/vendorNew.js","fn":"idleJudgement","note":"","line":34,"code":"  idleJudgement(s) {\n    const h = this.heatOf(s);\n    let p = this.BASE_IDLE;\n    if (h >= this.HEAT_HOT_THRESHOLD) p = this.HOT_IDLE;\n    else if (s.zeroStreak >= this.COLD_STREAK_THRESHOLD) p = this.COLD_IDLE;\n    if (Math.random() < p) s.state = 'new_unused';\n  },","usedBy":["VendorNew.idleJudgement"]},"agents/vendorNew.js#relocationJudgement":{"file":"agents/vendorNew.js","fn":"relocationJudgement","note":"","line":70,"code":"  // 搬遷規則：人氣旺就暫停倒數、留在原地；不旺才計時，依 Site Fertility Weighting 加權挑一個空店鋪搬過去，原位置變回空店鋪。\n  // 單位＝店鋪（World.shops，同 code 分組），不是個別 grid id——搬遷=兩家店鋪整組交換狀態。\n  relocationJudgement(s) {\n    if (this.heatOf(s) >= this.HEAT_HOT_THRESHOLD) return;\n    s.moveTimer--;\n    if (s.moveTimer > 0) return;\n    const blanks = World.shops.filter(x => x.state === 'blank');\n    if (blanks.length > 0) {\n      const target = this.pickFertileBlank(blanks);\n      target.state = s.state;\n      target.moveTimer = this.randMoveTicks();\n      target.visitHist = [0, 0];\n      target.zeroStreak = 0;\n      s.state = 'blank';\n      s.moveTimer = 0;\n    } else {\n      s.moveTimer = this.randMoveTicks();\n    }\n  },","usedBy":["VendorNew.relocationJudgement"]},"agents/vendorNew.js#visFertility":{"file":"agents/vendorNew.js","fn":"visFertility","note":"","line":54,"code":"  // (3) 可見度項：shop.visibility 隱蔽（< VIS_LOW）0、一般 VIS_FERTILITY_MID、顯眼（> VIS_HIGH）VIS_FERTILITY_HIGH，兩級固定值。\n  visFertility(shop) {\n    const P = CONFIG.params;\n    return shop.visibility < P.VIS_LOW ? 0 : shop.visibility > P.VIS_HIGH ? P.VIS_FERTILITY_HIGH : P.VIS_FERTILITY_MID;\n  },","usedBy":["VendorNew.siteFertility"]},"agents/vendorNew.js#shopFertility":{"file":"agents/vendorNew.js","fn":"shopFertility","note":"","line":42,"code":"  // Site Fertility Weighting：空店鋪的搬遷權重＝行為痕跡＋建築先天條件，兩項相加：\n  // (1) 該店鋪所有格子的 touristTrailHeat+residentTrailHeat 總和（全域變數，定義於 index.html，\n  //     見 simulator_setting.md「視覺效果—動線／路徑」）——地點過去被驗證過的人氣，累積出來的軟資料。\n  // (2) shop.corridorFrontage × FRONTAGE_SCALE——讀 World.cellSpace（Cell Attribute 陣列，website/agents/cell.js）\n  //     算出來的店面臨走道比例，地點本身的先天可及性，就算從未被使用過（痕跡=0）也不會跟其他空格沒有差別。\n  // ＋ FERTILITY_BASE_WEIGHT 底線，避免三項都是 0 時永久死鎖。\n  shopFertility(shop) {\n    let heat = 0;\n    for (const c of shop.cells) heat += touristTrailHeat[c.row][c.col] + residentTrailHeat[c.row][c.col];\n    return heat + shop.corridorFrontage * this.FRONTAGE_SCALE + this.visFertility(shop) + this.FERTILITY_BASE_WEIGHT;\n  },","usedBy":["VendorNew.siteFertility"]},"agents/vendorNew.js#pickFertileBlank":{"file":"agents/vendorNew.js","fn":"pickFertileBlank","note":"","line":60,"code":"  pickFertileBlank(blanks) {\n    const weights = blanks.map(b => this.shopFertility(b));\n    let r = Math.random() * weights.reduce((a, b) => a + b, 0);\n    for (let i = 0; i < blanks.length; i++) {\n      r -= weights[i];\n      if (r <= 0) return blanks[i];\n    }\n    return blanks[blanks.length - 1];\n  },","usedBy":["VendorNew.siteFertility"]},"agents/vendorNew.js#stepTick":{"file":"agents/vendorNew.js","fn":"stepTick","note":"","line":90,"code":"  stepTick() {\n    const mine = World.shops.filter(s => s.state === 'new');\n    mine.forEach(s => this.updateHeatHistory(s));\n    mine.forEach(s => this.idleJudgement(s));\n    // 這輪剛變 new_unused 的不在這裡搬遷，改由 VendorIdle 接手（狀態互斥，不會漏拍）。\n    World.shops.filter(s => s.state === 'new').forEach(s => this.relocationJudgement(s));\n  }","usedBy":["VendorNew.stepTick"]},"agents/vendorNew.js#initStall":{"file":"agents/vendorNew.js","fn":"initStall","note":"","line":18,"code":"  initStall(s) {\n    s.moveTimer = this.randMoveTicks();\n    s.visitHist = [0, 0];\n    s.zeroStreak = 0;\n  },","usedBy":["VendorNew.initStall"]},"agents/vendorNew.js#heatOf":{"file":"agents/vendorNew.js","fn":"heatOf","note":"","line":24,"code":"  heatOf(s) { return s.visitHist.reduce((a, b) => a + b, 0); },","usedBy":["VendorNew.heatOf"]},"agents/vendorNew.js#updateHeatHistory":{"file":"agents/vendorNew.js","fn":"updateHeatHistory","note":"","line":26,"code":"  updateHeatHistory(s) {\n    const v = Math.round(s._visitTick || 0); // _visitTick 已乘 VISIT_NORM 歸一回舊量級（見 index.html），取整數才跟人氣門檻同單位\n    s.visitHist.push(v);\n    if (s.visitHist.length > this.HEAT_WINDOW) s.visitHist.shift();\n    s.zeroStreak = v === 0 ? s.zeroStreak + 1 : 0;\n    s._visitTick = 0;\n  },","usedBy":["VendorNew.updateHeatHistory"]},"agents/vendorOld.js#stepTick":{"file":"agents/vendorOld.js","fn":"stepTick","note":"（空實作）","line":6,"code":"  stepTick() {}    // 沒有規則要跑","usedBy":["VendorOld.fixed"]},"agents/cell.js#buildCellSpace":{"file":"agents/cell.js","fn":"buildCellSpace","note":"","line":6,"code":"  // 建立 World.cellSpace：只有攤位格（stallslot）算 corridorFrontage，其餘格型（牆/設施/入口/走道）用不到，存 null。\n  buildCellSpace() {\n    const space = [];\n    for (let r = 0; r < World.ROWS; r++) {\n      const row = [];\n      for (let c = 0; c < World.COLS; c++) {\n        const t = World.cellType[r][c];\n        // 走道格：occupiedBy＝QGIS 標定「有資格擺椅的店鋪 code」（ERA_DATA，固定不變、不改寫）；椅子是否擺出見下方 chairCount。\n        // 攤位格：zone 是桌面／設備 → noEnter（行人不進）；zone 是用餐區 → 自己這家店的椅子（occupiedBy＝[自己的 code]，用餐區一律有椅子）。\n        if (t === 'stallslot') {\n          const zone = (ERA_DATA.cells[r + ',' + c] || {})['zone_' + this.SIM_ERA];\n          row.push({ corridorFrontage: this.frontageOf(r, c), noEnter: this.NO_ENTER_ZONES.includes(zone),\n            occupiedBy: zone === '用餐區' ? [World.stallAtRC[r + ',' + c].code] : [] });\n        } else row.push(t === 'aisle' ? { occupiedBy: (ERA_DATA.cells[r + ',' + c] || {}).occupiedBy || [] } : null);\n      }\n      space.push(row);\n    }\n    return space;\n  },","usedBy":["Cell.corridorFrontage","Cell.occupiedBy","Cell.noEnter"]},"agents/cell.js#frontageOf":{"file":"agents/cell.js","fn":"frontageOf","note":"","line":139,"code":"  // Attribute：corridorFrontage —— 這一格 4 個方向裡，臨走道／入口的邊數比例（0~1）。\n  // 是格子位置固定的物理量，只跟這一格在地圖上的位置有關，不隨哪個攤販進駐而改變。\n  frontageOf(r, c) {\n    let aisleEdges = 0;\n    for (const [dr, dc] of World.DIRS4) {\n      const nr = r + dr, nc = c + dc;\n      const t = (nr >= 0 && nr < World.ROWS && nc >= 0 && nc < World.COLS) ? World.cellType[nr][nc] : 'wall';\n      if (t === 'aisle' || t === 'entry') aisleEdges++;\n    }\n    return aisleEdges / 4;\n  },","usedBy":["Cell.corridorFrontage"]},"agents/cell.js#shopFrontage":{"file":"agents/cell.js","fn":"shopFrontage","note":"","line":151,"code":"  // 店鋪彙總：店鋪（同 code，多格）的 corridorFrontage ＝所屬格子的平均值，讀 World.cellSpace，不重算。\n  shopFrontage(shop) {\n    const sum = shop.cells.reduce((a, cell) => a + World.cellSpace[cell.row][cell.col].corridorFrontage, 0);\n    return sum / shop.cells.length;\n  }","usedBy":["Cell.corridorFrontage"]},"agents/cell.js#hasChair":{"file":"agents/cell.js","fn":"hasChair","note":"","line":68,"code":"  hasChair(r, c) { return this.chairCount(r, c) > 0; }, // 即 mobility＝Chair_Mobility，否則完全開放","usedBy":["Cell.mobility"]},"agents/cell.js#noEnter":{"file":"agents/cell.js","fn":"noEnter","note":"","line":29,"code":"  noEnter(r, c) { const cs = World.cellSpace[r][c]; return !!cs && !!cs.noEnter; },","usedBy":["Cell.noEnter"]},"agents/cell.js#densityAt":{"file":"agents/cell.js","fn":"densityAt","note":"","line":105,"code":"  densityAt(r, c) { return Math.max(0, (this.dens.get(r * World.COLS + c) || 0) - 1); }, // 減 1＝扣掉站在這裡的自己（周圍的人）","usedBy":["Cell.density"]},"agents/cell.js#buildVisibility":{"file":"agents/cell.js","fn":"buildVisibility","note":"","line":114,"code":"  // Attribute：visibility —— 有多少走道格看得到這格（阻擋判定同 Tourist.computeVisible），除以全圖攤位格最大值（0~1），存在 cellSpace 攤位格。\n  // 位置固定，開局算一次（computeStallGroups）；ponytail: 掃全部走道格×攤位格，地圖或視距放大後要改成射線外擴。\n  buildVisibility() {\n    const R = Tourist.visionRadius, counts = World.stalls.map(s => {\n      let n = 0;\n      for (const a of World.aisleCells) {\n        if (Math.abs(a.row - s.row) > R || Math.abs(a.col - s.col) > R) continue;\n        if (Tourist.computeVisible(a.row, a.col, s.row, s.col)) n++;\n      }\n      return n;\n    });\n    const max = Math.max(1, ...counts);\n    World.stalls.forEach((s, i) => { World.cellSpace[s.row][s.col].visibility = counts[i] / max; });\n  },","usedBy":["Cell.visibility"]},"agents/cell.js#shopVisibility":{"file":"agents/cell.js","fn":"shopVisibility","note":"","line":128,"code":"  // 店鋪彙總：所屬格子 visibility 的平均值，做法同 shopFrontage。\n  shopVisibility(shop) {\n    return shop.cells.reduce((a, cell) => a + World.cellSpace[cell.row][cell.col].visibility, 0) / shop.cells.length;\n  },","usedBy":["Cell.visibility"]}},"files":{"agents/cell.js":{"head":"Cell（市場網格空間本身）— 規則來源：agent_setting.md「Space Class」  Space Class 存成陣列：World.cellSpace，跟 World.cellType 一樣是 ROWS×COLS 的 2D 陣列，每一格自己的 Attribute。","lines":157,"fns":[{"fn":"buildCellSpace","used":true},{"fn":"noEnter","used":true},{"fn":"shopsReach","used":true},{"fn":"extentCells","used":false},{"fn":"hourNow","used":false},{"fn":"chairsOut","used":true},{"fn":"isOpen","used":true},{"fn":"chairCount","used":true},{"fn":"hasChair","used":true},{"fn":"seatsOf","used":true},{"fn":"hasSeat","used":true},{"fn":"tickPause","used":true},{"fn":"release","used":true},{"fn":"slowIfChair","used":true},{"fn":"trySit","used":true},{"fn":"passCost","used":true},{"fn":"refreshDensity","used":true},{"fn":"densityAt","used":true},{"fn":"crowdReact","used":true},{"fn":"buildVisibility","used":true},{"fn":"shopVisibility","used":true},{"fn":"preferNoChair","used":true},{"fn":"frontageOf","used":true},{"fn":"shopFrontage","used":true}]},"agents/resident.js":{"head":"Resident（逛老攤販的當地居民）— 規則來源：agent_setting.md「Resident」＋isovist_algorithm.md 第6-7點（residentStep）。  跟 Tourist 的差異：不用 isovist，全市場已知路線直接抄近路走（Wayfinding 文獻：熟悉環境者用既有認知地圖抄捷徑）。","lines":171,"fns":[{"fn":"reset","used":false},{"fn":"passableFor","used":true},{"fn":"bfsFieldFromTargets","used":true},{"fn":"fieldGet","used":false},{"fn":"randomStep","used":false},{"fn":"bestStepByField","used":true},{"fn":"exitStep","used":true},{"fn":"spawnExpected","used":true},{"fn":"move","used":true},{"fn":"step","used":true},{"fn":"draw","used":false},{"fn":"drawIso","used":false}]},"agents/tourist.js":{"head":"Tourist（逛新攤位的觀光客）— 規則來源：agent_setting.md「Tourist」＋isovist_algorithm.md pseudocode。  對照範例：20260824/isovist_sim.html 的 isVisible()/findVisibleTarget()/findVisiblePeer()/greedyStepToward()，函式名稱刻意保持一致方便對照。","lines":349,"fns":[{"fn":"reset","used":false},{"fn":"passableFor","used":true},{"fn":"bresenhamCells","used":false},{"fn":"isVisible","used":true},{"fn":"visibleStalls","used":false},{"fn":"computeVisible","used":false},{"fn":"heatBonus","used":true},{"fn":"chairBonus","used":true},{"fn":"visBonus","used":true},{"fn":"findVisibleTarget","used":true},{"fn":"findVisiblePeer","used":true},{"fn":"greedyStepToward","used":true},{"fn":"randomStep","used":false},{"fn":"bfsFieldToAisle","used":false},{"fn":"computeBfsFieldToAisle","used":false},{"fn":"fieldGet","used":false},{"fn":"bestStepByField","used":true},{"fn":"exitStep","used":true},{"fn":"spawnExpected","used":true},{"fn":"move","used":true},{"fn":"step","used":true},{"fn":"draw","used":false},{"fn":"drawIso","used":false},{"fn":"getVisibleCells","used":false},{"fn":"getDemoVisibleCells","used":false},{"fn":"drawVisionHighlight2D","used":false},{"fn":"drawVisionHighlightIso","used":false}]},"agents/vendorIdle.js":{"head":"Vendor (Idle)（已關門的攤販，不分新舊）— 規則來源：agent_setting.md「Vendor (Idle)」  世代＝老（state:'old_unused'）：固定規則，完全靜止；Vendor (Old) 現行規則不會關門，這裡現行不會被觸發。","lines":19,"fns":[{"fn":"stepTick","used":true}]},"agents/vendorNew.js":{"head":"Vendor (New)（正在營業的新創攤位）— 規則來源：agent_setting.md「Vendor (New)」","lines":98,"fns":[{"fn":"randMoveTicks","used":false},{"fn":"initStall","used":true},{"fn":"heatOf","used":true},{"fn":"updateHeatHistory","used":true},{"fn":"idleJudgement","used":true},{"fn":"shopFertility","used":true},{"fn":"visFertility","used":true},{"fn":"pickFertileBlank","used":true},{"fn":"relocationJudgement","used":true},{"fn":"stepTick","used":true}]},"agents/vendorOld.js":{"head":"Vendor (Old)（正在營業的老攤商）— 規則來源：agent_setting.md「Vendor (Old)」  ⚠️ 使用者指示覆寫（2026-08-24）：老攤商永久不會倒，拿掉原本的關門機率判定（人氣/冷清度/關門機率整段不再適用）。","lines":8,"fns":[{"fn":"initStall","used":false},{"fn":"stepTick","used":true}]}}};
